`timescale 1ns / 1ps

// mul_core u_dralm6: unsigned 16 x 16 -> 32, unsigned DR-ALM-6 (Yin 2021).
// Reference model: approx/mulbench.py.
// Generated by python3 -m src_gan_tsmc65.approx.mulbench (do not edit).

// logarithmic converter: x (> 0) -> {k, x_t}, k = leading-one position, x_t = the
// 4 bits after the leading one and a forced 1 (dynamic truncation, t = 6)
module dralm_t6u_16_log (
    input  wire [15:0] x,
    output wire [8:0] l
);
    reg [3:0] k;
    integer i;
    always @* begin
        k = 0;
        for (i = 1; i < 16; i = i + 1)
            if (x[i]) k = i;
    end
    wire [15:0] xs = x << (15 - k);       // leading one to bit 15
    assign l = {k, xs[14:11], 1'b1};
endmodule

// antilogarithmic converter + shifter: P = {1, L[t-2:0]} * 2^(L[top:t-1] - (t-1)),
// bits below the binary point dropped
module dralm_t6u_16_antilog (
    input  wire [9:0] l,
    output wire [31:0] p
);
    wire [5:0] mant = {1'b1, l[4:0]};
    wire [4:0] e = l[9:5];
    wire [36:0] s = {{(31){1'b0}}, mant} << e;
    assign p = s[36:5];
endmodule

module mul_core (
    input  wire [15:0]  a,
    input  wire [15:0]  b,
    output wire [31:0] p
);
    // unsigned operands: no sign units
    wire [15:0] ma = a;
    wire [15:0] mb = b;
    wire [8:0] la, lb;
    dralm_t6u_16_log u_la (.x(ma), .l(la));
    dralm_t6u_16_log u_lb (.x(mb), .l(lb));
    // adder + compensation: both x_t LSBs are 1 and +2^-(t-1) is added, so the sum LSB
    // is 1 and the upper bits get a carry-in of 1
    wire [8:0] hi = la[8:1] + lb[8:1] + 1'b1;
    wire [9:0] l = {hi, 1'b1};
    wire [31:0] m;
    dralm_t6u_16_antilog u_al (.l(l), .p(m));
    wire zero = ~|a | ~|b;
    assign p = zero ? 32'd0 : m;
endmodule
